import{_ as p,c as e,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"5、【需】 乾下坎上","description":"周易集注 - 5、【需】 乾下坎上","frontmatter":{"title":"5、【需】 乾下坎上","description":"周易集注 - 5、【需】 乾下坎上"},"headers":[],"relativePath":"zh/classics/jizhu/009.md","filePath":"zh/classics/jizhu/009.md"}'),l={name:"zh/classics/jizhu/009.md"};function t(h,a,s,n,c,d){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="_5、【需】-乾下坎上" tabindex="-1">5、【需】 乾下坎上 <a class="header-anchor" href="#_5、【需】-乾下坎上" aria-label="Permalink to “5、【需】 乾下坎上”">​</a></h1><p>需者须也，有所待也，理势不得不需者。以卦象论，水在天上，未遽下于地，必待阴阳之交，薰蒸而后成，需之象也。以卦德论，干性主于必进，乃处坎陷之下，未肯遽进，需之义也。《序卦》：“蒙者物之穉也，物穉不可不养也。需者，饮食之道也。”养物以饮食，所以次蒙。</p><p>需虽有所待，乃我所当待也，非不当待而待也。孚者，信之在中者也。坎体诚信，克实于中，孚之象也。光者此心光明，不为私欲所蔽也。中爻离，光明之象也。亨者，此心亨泰，不为私欲所窒也。坎为通，亨通之象也。贞者事之正也。八卦正位，坎在五，阳刚中正，为需之主，正之象也，皆指五也。坎水在前，乾健临之。干知险，涉大川之象也。又中爻兑综巽，坎水在前，巽木临之，亦涉大川之象，详见颐卦上九。孚贞者，尽所需之道。光亨吉利者，得所需之效。需若无实，必无光亨之时。需若不正，岂有吉利之理。</p><p>言事若有所待，而心孚信，则光明而亨通矣。而事又出于其正，不行险以侥幸，则吉矣，故利涉大川。</p><p>《彖》曰：需须也，险在前也。刚健而不陷，其义不困穷矣。需有孚，光亨，贞吉，位乎天位，以正中也。利涉大川，往有功也。</p><p>以卦德释卦名，以卦综释卦辞。需者须也，理势之所在，正欲其有所待也，故有需之义。险在前，不易于进，正当需之时也。干临之，毅然有守，不冒险以前进，故不陷于险。既不陷于险，则终能出其险，其义不至于困穷矣，所以名需。需讼二卦同体，文王综为一卦，故《杂卦》曰“需不进也，讼不亲也”。位天位以正中者，讼下卦之坎，往居需之上卦，九五又正而又中也，五为天位，因自讼之地位往居之，故曰位乎天位。如在讼下卦，止可言中，不可言正矣。正则外无偏倚，中则心无夹杂，所以有孚，光亨贞，往有功，与渐蹇解三卦彖辞往有功同，言讼下卦，往而居需之上卦，九五正中，所以有利涉大川之功也。</p><p>《象》曰：云上于天，需，君子以饮食宴乐。</p><p>云气蒸而上升，必待阴阳和洽，然后成雨，故为需，待之义。君子事之当需者，亦不容更有所为，惟内有孚，外守正，饮食以养其气体而已，宴乐以娱其心志而已，此外别无所作为也。曰饮食宴乐者，乃居易俟命，涵养待时之象也，非真必饮食宴乐也。若伯夷太公，需待天下之清，穷困如此，岂能饮食宴乐哉。</p><p>初九，需于郊，利用恒，无咎。</p><p>郊者，旷远之地，未近于险之象也。干为郊，郊之象也，故同人小畜皆言郊。需于郊者，不冒险以前进也。恒者常也，安常守静，以待时，不变所守之操也。利用恒无咎者，戒之也，言若无恒，犹有咎也。</p><p>初九阳刚得正，未近于险，乃不冒险以前进者，故有需郊之象。然需于始者，或不能需于终，故必义命自安，恒于郊而不变，乃其所利也。戒占者能如此则无咎矣，</p><h3 id="《象》曰-需于郊-不犯难行也。利用恒无咎-未失常也。-难乃旦反" tabindex="-1">《象》曰：需于郊，不犯难行也。利用恒无咎，未失常也。(难乃旦反) <a class="header-anchor" href="#《象》曰-需于郊-不犯难行也。利用恒无咎-未失常也。-难乃旦反" aria-label="Permalink to “《象》曰：需于郊，不犯难行也。利用恒无咎，未失常也。(难乃旦反)”">​</a></h3><p>不犯难行者，超然远去，不冒犯险难以前进也。未失常者，不失需之常道也，需之常道，不过以义命自安，不冒险以前进而已。</p><p>九二，需于沙，小有言，终吉。</p><p>坎为水，水近则有沙，沙则近于险矣。渐近于险，虽未至于患害，已小有言矣。小言者，众人见讥之言也。避世之士，知前有坎陷之险，责之以洁身，用世之士，知九二刚中之才，责之以拯溺也。中爻为兑口舌，小言之象也。终吉者，变爻离明，明哲保身，终不陷于险矣。</p><p>二以阳刚之才，而居柔守中，盖不冒险而进者，故有需于沙之象。占者如是，虽不免小有言，终得其吉也。</p><h3 id="《象》曰-需于沙-衍在中也。虽小有言-以吉终也。" tabindex="-1">《象》曰：需于沙，衍在中也。虽小有言，以吉终也。 <a class="header-anchor" href="#《象》曰-需于沙-衍在中也。虽小有言-以吉终也。" aria-label="Permalink to “《象》曰：需于沙，衍在中也。虽小有言，以吉终也。”">​</a></h3><p>水行朝宗曰衍，即水字也。凡江河，水在中而沙在边。衍在中者，言水在中央也。沙在水边则近于险矣，虽近于险而小有言，然以刚中处需，故不陷于险而以吉终也。</p><p>九三，需于泥，致寇至。</p><p>泥逼于水，将陷于险矣，寇之地也。坎为盗在前，寇之象也。</p><p>九三居健体之上，才位俱刚，进不顾前，迩于坎盗，故有需泥寇至之象。健体敬慎惕若，故占者不言凶。</p><h3 id="《象》曰-需于泥-灾在外也。自我致寇-敬慎不败也。" tabindex="-1">《象》曰：需于泥，灾在外也。自我致寇，敬慎不败也。 <a class="header-anchor" href="#《象》曰-需于泥-灾在外也。自我致寇-敬慎不败也。" aria-label="Permalink to “《象》曰：需于泥，灾在外也。自我致寇，敬慎不败也。”">​</a></h3><p>外谓外卦，灾在外者，言灾已切身，而在目前也。灾在外而我近之，是致寇自我也。敬慎不败者，三得其正，乾乾惕若，敬而且慎，所以不败于寇也。故占者不言凶。</p><p>六四，需于血，出自穴。</p><p>坎为血，血之象也，又为隐伏，穴之象也。偶居左右上下皆阳，亦穴之象也。血即坎字，非见伤也。出自穴者，观上六入于穴入字，此言出字，即出入二字自明矣。言虽需于血，然犹出自穴外，未入于穴之深也。需卦近于坎，致寇至及入于坎，三爻皆吉者何也?盖六四顺于初之阳，上六阳来救援，皆应与有力。九五中正，所以皆吉也。凡看周公爻辞，要玩孔子小象，若以血为杀伤之地，失小象顺听之旨矣。</p><p>四交于坎，已入于险，故有需于血之象。然四与初为正应，能顺听乎初，初乃乾刚至健而知险，惟知其险，是出自穴外，不冒险以进，虽险而不险矣，故其象占如此。</p><h3 id="《象》曰-需于血-顺以听也。" tabindex="-1">《象》曰：需于血，顺以听也。 <a class="header-anchor" href="#《象》曰-需于血-顺以听也。" aria-label="Permalink to “《象》曰：需于血，顺以听也。”">​</a></h3><p>坎为耳，听之象也。听者，听乎初也。六四柔得其正，顺也。顺听乎初，故入险不险。</p><p>九五，需于酒食，贞吉。</p><p>坎，水酒象。中爻兑，食象。详见困卦。酒食，宴乐之具。需于酒食者，安于日用饮食之常，以待之而已。贞吉者，正而自吉也，非戒也。</p><p>九五，阳刚中正，居于尊位，盖优游和平，不多事以自扰，无为而治者也，故有需于酒食之象，其贞吉可知矣。占者有是贞，亦有是吉也，</p><h3 id="《象》曰-酒食贞吉-以正中也-。" tabindex="-1">《象》曰：酒食贞吉，以正中也*。 <a class="header-anchor" href="#《象》曰-酒食贞吉-以正中也-。" aria-label="Permalink to “《象》曰：酒食贞吉，以正中也*。”">​</a></h3><p>即彖正中。</p><ul><li>一般皆做“以中正也”，来氏作“以正中也”。</li></ul><p>上六，入于穴，有不速之客三人来，敬之，终吉。</p><p>阴居险陷之极，入于穴之象也，变巽为入，亦入之象也。下应九三，阳合乎阴，阳主上进，不召请而自来之象也。我为主，应为客，三阳同体，客三人之象也。入穴穷困，望人救援之心甚切，喜其来而敬之之象也。终吉者，以阳至健知险，可以极溺也。</p><p>上六居险之极，下应九三，故其象如此。占者之吉可知矣，</p><h3 id="《象》曰-不速之客来-敬之终吉-虽不当位-未大失也。-当去声" tabindex="-1">《象》曰：不速之客来，敬之终吉，虽不当位，未大失也。(当去声) <a class="header-anchor" href="#《象》曰-不速之客来-敬之终吉-虽不当位-未大失也。-当去声" aria-label="Permalink to “《象》曰：不速之客来，敬之终吉，虽不当位，未大失也。(当去声)”">​</a></h3><p>位者爻位也，三乃人位，应乎上六，故曰人来。初与二皆地位，上六所应者乃人位，非地位。今初与二皆来，故不当位也。以一阴而三阳之来，上六敬之，似为失身矣，而不知入于其穴，其时何时也。来救援于我者，犹择其位之当否，而敬有分别，是不知权变者矣，故初与二，虽不当位，上六敬之，亦未为大失也。曰未大失者，言虽失而未大也。若不知权变，自经于沟渎，且失愈大矣，易中之时，正在于此。</p>',39)])])}const f=p(l,[["render",t]]);export{_ as __pageData,f as default};
